private void refreshOnlineMap() {
    if (this.map == null) {
        return;
    }
    try {
        Configuration.getInstance().setExpirationOverrideDuration(0L);
        this.map.getTileProvider().clearTileCache();
        applyMapType();
        Toast.makeText(this, "已清理地图缓存，将绕过旧缓存重新请求在线瓦片", 1).show();
    } catch (Exception e) {
        Toast.makeText(this, "地图刷新失败：" + safeMessage(e), 1).show();
    }
}
